// Package kernel is the shared kernel (spec section 2.2): identifiers, the
// value model, versions, domain errors, the clock, and job requests.
package kernel

import (
	"fmt"

	"github.com/google/uuid"
)

// ID identifies a feature or principal. IDs are generated by the
// application, never by a database (spec 3.4).
type ID [16]byte

// NilID is the zero ID.
var NilID ID

// ParseID parses the canonical UUID text form.
func ParseID(s string) (ID, error) {
	u, err := uuid.Parse(s)
	if err != nil {
		return NilID, fmt.Errorf("invalid id %q", s)
	}
	return ID(u), nil
}

// MustParseID parses s and panics on error; for tests and static fixtures.
func MustParseID(s string) ID {
	id, err := ParseID(s)
	if err != nil {
		panic(err)
	}
	return id
}

// String returns the canonical UUID text form.
func (id ID) String() string { return uuid.UUID(id).String() }

// IsZero reports whether id is the nil ID.
func (id ID) IsZero() bool { return id == NilID }

// MarshalText implements encoding.TextMarshaler.
func (id ID) MarshalText() ([]byte, error) { return []byte(id.String()), nil }

// UnmarshalText implements encoding.TextUnmarshaler.
func (id *ID) UnmarshalText(b []byte) error {
	p, err := ParseID(string(b))
	if err != nil {
		return err
	}
	*id = p
	return nil
}

// IDGenerator produces new IDs.
type IDGenerator interface {
	NewID() ID
}

// UUIDv7Generator generates time-ordered UUIDv7 IDs (spec 3.4).
type UUIDv7Generator struct{}

// NewID returns a new UUIDv7.
func (UUIDv7Generator) NewID() ID {
	u, err := uuid.NewV7()
	if err != nil {
		// uuid.NewV7 fails only when the system random source fails.
		panic(fmt.Sprintf("uuid v7: %v", err))
	}
	return ID(u)
}
